function oobe () {
    game.setDialogFrame(assets.image`Box01`)
    game.showLongText("Welcome To LEGACYOS", DialogLayout.Bottom)
    game.showLongText("The open-source OS that carries a LEGACY to empower users.", DialogLayout.Bottom)
    users = [game.askForString("What's your name?")]
    blockSettings.writeStringArray("usernames", users)
}
function userSelect () {
	
}
let users: string[] = []
let currentUserName: string;
let logoText = fancyText.create("LegacyOS")
pause(500)
scene.setBackgroundColor(1)
fancyText.setColor(logoText, 15)
pause(500)
scene.setBackgroundColor(15)
fancyText.setColor(logoText, 5)
pause(500)
scene.setBackgroundColor(5)
fancyText.setColor(logoText, 15)
let loaderBar = statusbars.create(scene.screenWidth(), 4, StatusBarKind.Health)
loaderBar.positionDirection(CollisionDirection.Bottom)
loaderBar.value = 0
for (let index = 0; index < 8; index++) {
    music.play(music.createSoundEffect(WaveShape.Noise, 5000, 5000, 255, 255, 200, SoundExpressionEffect.None, InterpolationCurve.Linear), music.PlaybackMode.UntilDone)
    loaderBar.value += 10
}
pause(200)
for (let index = 0; index < 20; index++) {
    pause(20)
    music.play(music.createSoundEffect(WaveShape.Noise, 2431, 2239, 255, 255, 10, SoundExpressionEffect.Vibrato, InterpolationCurve.Linear), music.PlaybackMode.InBackground)
    loaderBar.value += 1
}
sprites.destroy(loaderBar)
pause(200)
music.play(pianoRoll.createSong(hex``), music.PlaybackMode.UntilDone)
sprites.destroy(logoText)
if (blockSettings.exists("usernames")) {
    userSelect()
} else {
    oobe()
}
